INSERT INTO UTILISATEUR_ROLE (UTILISATEUR_ID, ROLE_ID, DATE_DEBUT, MOTIF)
SELECT u.ID, r.ID, TRUNC(SYSDATE), 'Compte de demonstration' FROM UTILISATEUR u JOIN ROLE_RH r ON r.CODE = 'ADMIN'
 WHERE u.LOGIN = 'admin' AND NOT EXISTS (SELECT 1 FROM UTILISATEUR_ROLE ur WHERE ur.UTILISATEUR_ID = u.ID AND ur.ROLE_ID = r.ID AND ur.DATE_FIN IS NULL);
